@extends('layouts.app')
@section('title', 'Master KPI · KPI Kinerja')
@section('content')
<section x-data="templatesPage" @cycle-changed.window="load()"><div class="page-heading"><div><h1 x-text="readonly ? 'KPI unit' : ui.page==='import' ? 'Impor Master KPI' : 'Master KPI'"></h1><p x-text="readonly ? 'Template sesuai jabatan dan periode. Bobot dan acuan pengukuran hanya baca.' : 'Kelola template per jabatan, tahun, dan versi. Total bobot wajib 100%.'"></p></div><div class="button-row" x-show="!readonly"><a class="btn" href="/hc/import">Impor template</a><button class="btn btn-primary" @click="edit()"><x-icon name="plus"/>Tambah template</button></div></div>
<div class="panel panel-pad mb-5" x-show="ui.page==='import'"><h2 class="panel-title">Unggah dan periksa file</h2><p class="muted small mt-2">Gunakan CSV atau XLSX, lembar pertama, maksimal 200 KPI dan 2 MB. Formula Excel tidak digunakan. Pratinjau tidak menyimpan perubahan.</p><div class="toolbar mt-4"><div class="field !max-w-none"><label for="template-file">File template KPI</label><input id="template-file" type="file" accept=".csv,.xlsx" @change="previewFile($event)"></div><a class="btn" href="/hc/import/sample">Unduh contoh CSV</a></div><p class="notice" x-show="importBusy" role="status">Memeriksa file…</p><p class="notice notice-error" x-show="importError" x-text="importError" role="alert"></p><template x-if="imported"><div class="stack"><div class="notice" :class="{'notice-warning':!imported.valid}"><strong x-text="imported.items.length+' KPI · total bobot '+$number(imported.weight_total,4)+'%'"></strong><template x-for="(messages,key) in imported.errors" :key="key"><p class="small" x-text="key+': '+messages[0]"></p></template><p x-show="imported.valid">Seluruh baris valid. Lengkapi identitas template sebelum menyimpan draft.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Pilar</th><th>KPI</th><th>Target</th><th class="numeric">Bobot</th></tr></thead><tbody><template x-for="(item,index) in imported.items" :key="index"><tr><td x-text="item.pillar"></td><td x-text="item.name"></td><td x-text="item.target_text"></td><td class="numeric" x-text="$number(item.weight_percent,4)+'%'"></td></tr></template></tbody></table></div><button class="btn btn-primary justify-self-end" :disabled="!imported.valid" @click="applyImport()">Lanjutkan sebagai draft template</button></div></template></div>
<div class="toolbar"><div class="field"><label for="template-position">Jabatan</label><select id="template-position" x-model="positionFilter" @change="load()"><option value="">Semua jabatan</option><template x-for="position in lookups.positions" :key="position.id"><option :value="position.id" x-text="position.name"></option></template></select></div><div class="field" x-show="!readonly"><label for="template-year">Tahun</label><input id="template-year" type="number" min="2000" max="2200" x-model="year" @change="load()"></div></div><x-page-state empty="!rows.length" title="Template belum tersedia" message="Belum ada template sesuai jabatan dan periode yang dipilih. Template dikelola Super HC."/><div x-cloak x-show="!loading && !loadError && rows.length"><div class="table-wrap"><table class="table"><thead><tr><th>Template</th><th>Jabatan</th><th>Versi</th><th>Status</th><th>Masa berlaku</th><th>Tindakan</th></tr></thead><tbody><template x-for="row in rows" :key="row.id"><tr><td><strong x-text="row.name"></strong><span class="subtext" x-text="'Tahun '+row.template_year"></span></td><td x-text="positionName(row.position_id)"></td><td x-text="'v'+row.version"></td><td><x-badge/></td><td class="small" x-text="(row.effective_from || 'Awal tahun')+' sampai '+(row.effective_until || 'Akhir tahun')"></td><td><div class="button-row"><button class="btn btn-small" @click="viewTemplate(row)">Lihat KPI</button><button class="btn btn-small" x-show="!readonly && row.status==='draft'" @click="edit(row)">Ubah</button><button class="btn btn-small" x-show="!readonly && row.status==='draft'" @click="publish(row)">Publikasikan</button><button class="btn btn-small" x-show="!readonly && row.status!=='draft'" @click="edit(row,true)">Versi baru</button></div></td></tr></template></tbody></table></div><x-pagination/></div>
<dialog class="wide-dialog" x-ref="template" @click.self="!busy && $el.close()"><form class="dialog-body" @submit.prevent="save()"><div class="dialog-header"><h2 x-text="editingId?'Ubah draft template':'Tambah template KPI'"></h2><button class="icon-button" type="button" @click="$refs.template.close()" :disabled="busy" aria-label="Tutup editor template"><x-icon name="close"/></button></div><fieldset :disabled="templateReadonly || busy"><div class="form-grid"><div class="field full"><label for="template-name">Nama template</label><input id="template-name" x-model="form.name" required maxlength="190"></div><div class="field"><label for="editor-position">Jabatan</label><select id="editor-position" x-model="form.position_id" required :disabled="!!editingId"><option value="">Pilih jabatan</option><template x-for="position in lookups.positions.filter(p=>p.is_active)" :key="position.id"><option :value="position.id" x-text="position.name"></option></template></select></div><div class="field"><label for="editor-year">Tahun penilaian</label><input id="editor-year" type="number" min="2000" max="2200" x-model="form.template_year" required></div><div class="field"><label for="effective-from">Berlaku mulai</label><input id="effective-from" type="date" x-model="form.effective_from" required></div><div class="field"><label for="effective-until">Berlaku sampai</label><input id="effective-until" type="date" x-model="form.effective_until" required></div></div><p class="small muted my-4">Tanggal harus berada pada tahun template dan tidak bertumpang tindih dengan versi yang sudah dipublikasikan.</p><div class="stack"><template x-for="(item,index) in form.items" :key="index"><fieldset class="panel panel-pad"><legend class="sr-only" x-text="'KPI '+(index+1)"></legend><div class="flex justify-between items-center mb-3"><strong x-text="'KPI '+(index+1)"></strong><button class="icon-button" type="button" @click="removeItem(index)" :disabled="form.items.length===1" :aria-label="'Hapus KPI '+(index+1)"><x-icon name="trash"/></button></div><div class="form-grid"><div class="field"><label :for="'pillar-'+index">Pilar</label><select :id="'pillar-'+index" x-model="item.pillar" required><template x-for="pillar in pillars" :key="pillar"><option x-text="pillar"></option></template></select></div><div class="field"><label :for="'kpi-name-'+index">Nama KPI</label><input :id="'kpi-name-'+index" x-model="item.name" required maxlength="255"></div><template x-for="field in [['numerator','Numerator'],['denominator','Denominator'],['measurement_formula','Formula pengukuran'],['target_text','Target (teks)']]" :key="field[0]"><div class="field"><label :for="field[0]+'-'+index" x-text="field[1]"></label><input :id="field[0]+'-'+index" x-model="item[field[0]]" :maxlength="field[0]==='target_text'?255:10000"></div></template><div class="field"><label :for="'weight-'+index">Bobot (%)</label><input :id="'weight-'+index" x-model="item.weight_percent" required inputmode="decimal" pattern="[0-9]{1,3}([.,][0-9]{1,4})?"></div></div><p class="field-error" x-text="errors['items.'+index+'.name']?.[0] || errors['items.'+index+'.weight_percent']?.[0] || ''"></p></fieldset></template></div><div class="flex flex-wrap justify-between gap-4 mt-4"><button class="btn" type="button" @click="addItem()"><x-icon name="plus"/>Tambah KPI</button><p class="weight-total" :class="{invalid:weightTotal!==100}" x-text="'Total bobot '+$number(weightTotal,4)+'% dari 100%'"></p></div></fieldset><div class="notice notice-error mt-4" x-show="formError" role="alert"><p x-text="formError"></p><template x-for="(messages,key) in errors" :key="key"><p class="small mt-1" x-text="messages[0]"></p></template></div><div class="dialog-footer"><button class="btn" type="button" @click="$refs.template.close()" :disabled="busy">Batal</button><button class="btn btn-primary" type="submit" :disabled="busy || weightTotal!==100 || templateReadonly" x-text="busy?'Menyimpan…':'Simpan draft template'"></button></div></form></dialog>
<dialog class="wide-dialog" x-ref="preview" @click.self="$el.close()"><div class="dialog-body"><div class="dialog-header"><h2 x-text="selected?.name || 'Rincian KPI'"></h2><button class="icon-button" @click="$refs.preview.close()" aria-label="Tutup rincian KPI"><x-icon name="close"/></button></div><p class="muted small mb-4">Acuan pengukuran dan bobot template hanya baca.</p><div class="table-wrap"><table class="table"><thead><tr><th>Pilar / KPI</th><th>Numerator / denominator</th><th>Formula</th><th>Target</th><th class="numeric">Bobot</th></tr></thead><tbody><template x-for="item in selected?.items || []" :key="item.id"><tr><td><strong x-text="item.name"></strong><span class="subtext" x-text="item.pillar"></span></td><td><span x-text="item.numerator || 'Tidak ditentukan'"></span><span class="subtext" x-text="item.denominator || 'Tidak ditentukan'"></span></td><td x-text="item.measurement_formula || 'Tidak ditentukan'"></td><td x-text="item.target_text || 'Tidak ditentukan'"></td><td class="numeric" x-text="$number(item.weight_percent,2)+'%'"></td></tr></template></tbody></table></div><div class="dialog-footer"><button class="btn btn-primary" @click="$refs.preview.close()">Tutup</button></div></div></dialog></section>
@endsection
